// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address from = address(0x1);
        address caddress = address(0x2);
        address[] memory tos = new address[](1);
        tos[0] = address(0x3);
        uint[] memory vals = new uint[](1);
        vals[0] = 1;

        // Make the target contract (caddress) a simple test contract that records calls
        // We'll deploy a minimal contract at caddress that reverts if called with the expected selector
        vm.etch(caddress, type(Spy).runtimeCode);
        // Deploy spy contract at caddress
        Spy spy = Spy(caddress);

        // Call transfer
        bool ok;
        try c.transfer(from, caddress, tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "transfer should return true");

        // The spy reverts if it was called, so if reference called it, the spy would have reverted
        // But we need a different observable: check that the spy's `called` flag was set to true
        assertTrue(spy.called(), "reference should have made the call");
    }
}

contract Spy {
    bool public called;
    fallback(bytes calldata) external returns (bytes memory) {
        called = true;
        return abi.encode(true);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract Receiver {
    bool public called;
    function transferFrom(address, address, uint256) external returns (bool) {
        called = true;
        return true;
    }
}

contract InvMutTest is Test {
    C c;
    Receiver receiver;
    function setUp() public { 
        c = new C(); 
        receiver = new Receiver();
    }
    function testRegression_property() public {
        address[] memory tos = new address[](1);
        tos[0] = address(0x3);
        uint[] memory vals = new uint[](1);
        vals[0] = 100;
        c.transfer(address(0x1), address(receiver), tos, vals);
        assertTrue(receiver.called());
    }
}

